<div class="table-wrap"><table class="data-table"><thead><tr><?php if (in_array($section, ['propiedades','publicaciones','buscar-propiedades','favoritos'], true)): ?><th>Oportunidad</th><th>Zona</th><th>Operación</th><th>Precio</th><th>Estado</th><?php elseif (in_array($section, ['emprendimientos','obras'], true)): ?><th>Proyecto</th><th>Ubicación</th><th>Unidades</th><th>Avance</th><th>Estado</th><?php elseif ($section === 'unidades'): ?><th>Unidad</th><th>Proyecto</th><th>Tipología</th><th>Precio</th><th>Disponibilidad</th><?php elseif (in_array($section, ['reservas','ventas'], true)): ?><th>Unidad</th><th>Proyecto</th><th>Cliente</th><th>Estado</th><th>Fecha</th><?php elseif (in_array($section, ['visitas','agenda'], true)): ?><th>Propiedad</th><th>Cliente</th><th>Fecha</th><th>Estado</th><th>Zona</th><?php else: ?><th>Contacto</th><th>Motivo</th><th>Propiedad</th><th>Estado</th><th>Recibido</th><?php endif; ?></tr></thead><tbody>
<?php foreach ($rows as $row): ?><tr>
<?php if (in_array($section, ['propiedades','publicaciones','buscar-propiedades','favoritos'], true)): ?><td><a class="table-primary" href="<?= e(url('/properties/' . rawurlencode($row['slug']))) ?>"><?= e($row['title']) ?></a><span class="table-secondary"><?= e(ucfirst($row['type'])) ?></span></td><td><?= e($row['city']) ?>, <?= e($row['province']) ?></td><td><?= $row['operation'] === 'rent' ? 'Alquiler' : 'Venta' ?></td><td><?= e(money($row['price'], $row['currency'])) ?></td><td><span class="status-pill"><?= e(ucfirst($row['status'])) ?></span></td>
<?php elseif (in_array($section, ['emprendimientos','obras'], true)): ?><td><span class="table-primary"><?= e($row['name']) ?></span><span class="table-secondary"><?= e($row['description']) ?></span></td><td><?= e($row['city']) ?>, <?= e($row['province']) ?></td><td><?= e($row['unit_count'] ?? 0) ?></td><td><div class="progress-track"><span style="width:<?= e(min(100, (int) $row['progress_percent'])) ?>%"></span></div><?= e($row['progress_percent']) ?>%</td><td><span class="status-pill"><?= e(str_replace('_', ' ', ucfirst($row['status']))) ?></span></td>
<?php elseif ($section === 'unidades'): ?><td><span class="table-primary"><?= e($row['unit_code']) ?></span></td><td><?= e($row['project_name']) ?></td><td><?= e($row['type']) ?><?= $row['bedrooms'] ? ' · ' . e($row['bedrooms']) . ' dorm.' : '' ?></td><td><?= e(money($row['price'], $row['currency'])) ?></td><td><span class="status-pill"><?= e(ucfirst($row['status'])) ?></span></td>
<?php elseif (in_array($section, ['reservas','ventas'], true)): ?><td><?= e($row['unit_code']) ?></td><td><?= e($row['project_name']) ?></td><td><?= e($row['client_name'] ?? 'Interesado') ?></td><td><span class="status-pill"><?= e(ucfirst($row['status'])) ?></span></td><td><?= e(format_date($row['created_at'])) ?></td>
<?php elseif (in_array($section, ['visitas','agenda'], true)): ?><td><span class="table-primary"><?= e($row['property_title']) ?></span></td><td><?= e($row['client_name'] ?? 'Vos') ?></td><td><?= e(format_date($row['scheduled_at'], 'd/m/Y H:i')) ?></td><td><span class="status-pill"><?= e(ucfirst($row['status'])) ?></span></td><td><?= e($row['city'] ?? '') ?></td>
<?php else: ?><td><span class="table-primary"><?= e($row['name']) ?></span><a class="table-secondary" href="mailto:<?= e($row['email']) ?>"><?= e($row['email']) ?></a></td><td><?= e($row['subject']) ?></td><td><?= e($row['property_title'] ?? 'Consulta general') ?></td><td><span class="status-pill"><?= e(ucfirst($row['status'])) ?></span></td><td><?= e(format_date($row['created_at'])) ?></td><?php endif; ?>
</tr><?php endforeach; ?></tbody></table></div>
